function Rules({expanded=false}:{expanded?:boolean}){return <details className="panel rules"><summary>Punctajul gărzilor</summary><div className="point-rule"><span>1 P</span><p>Luni–vineri</p></div><div className="point-rule weekend-rule"><span>3 P</span><p>Weekend</p></div><div className="point-rule holiday-rule"><span>5 P</span><p>Sărbătoare legală</p></div><div className="point-rule holiday-rule"><span>10 P</span><p>Sărbătoare mare</p></div>{expanded&&<p className="rule-note">Regulamentul complet este în tabul „Reguli”. Refuzurile se scad din punctaj; gărzile consecutive nu se atribuie.</p>}</details>;}
function RulesPage(){return <><div className="page-heading"><div><h1>Reguli</h1><p>Regulamentul echipei pentru înscrieri, repartizare și punctaje.</p></div></div><div className="rules-page">{RULE_SECTIONS.map((section,index)=><section className="panel" key={section.title}><h2>{section.title}</h2><ol start={1+RULE_SECTIONS.slice(0,index).reduce((n,s)=>n+s.items.length,0)}>{section.items.map(item=><li key={item}>{item}</li>)}</ol></section>)}</div></>;}
function CalendarGrid({month,holidays,holidayPoints={},preferred=[],available=[],stage,onSelect,shifts=[],name,meId,onShift,showUncovered=false}:{month:string;holidays:Record<string,string>;holidayPoints?:Record<string,number>;preferred?:number[];available?:number[];stage?:number;onSelect?:(d:number)=>void;shifts?:Shift[];name?:(id:string)=>string;meId?:string;onShift?:(d:number)=>void;showUncovered?:boolean}){
 const offset=(new Date(month+"-01T12:00:00Z").getUTCDay()+6)%7;const cells=Math.ceil((offset+monthDays(month))/7)*7;
 return <div className="calendar-grid"><div className="week-labels">{["Lun","Mar","Mie","Joi","Vin","Sâm","Dum"].map((d,i)=><span key={d} className={i>4?"weekend-label":""}>{d}</span>)}</div><div className="calendar-cells">{Array.from({length:cells},(_,i)=>{
  const day=i-offset+1;if(day<1||day>monthDays(month))return <div className="day-cell blank" key={i}/>;
  const date=dateKey(month,day),rank=preferred.indexOf(day),availableRank=available.indexOf(day),isExtra=availableRank>=0,holiday=holidays[date],shift=shifts.find(s=>s.date===date),disabled=stage===2&&rank>=0,weekday=new Date(date+"T12:00:00Z").getUTCDay();
  const cls=`day-cell ${weekday===0||weekday===6?"weekend":""} ${holiday?"holiday":""} ${rank>=0?"preferred":""} ${isExtra?"available":""} ${shift&&meId&&shift.user_id===meId?"my-shift":""} ${onSelect?"interactive":""} ${!onSelect&&!shift?"unassigned":""} ${shift?"assigned":""} ${showUncovered&&!shift?"uncovered":""}`;
  const children=<><div className="day-top"><span>{day}</span>{onSelect&&rank>=0&&<span className="preference-rank">{rank+1}</span>}{onSelect&&isExtra&&<span className="preference-rank availability-rank">{availableRank+1}</span>}</div>{shift&&<span className="shift-name">{calendarDoctorName(name?.(shift.user_id)??"Medic")}</span>}</>;
  const accessible=`${dateLabel(date)}${holiday?`, ${holiday}`:""}${onSelect?(rank>=0?`, preferința ${rank+1}`:isExtra?`, disponibilitate ${availableRank+1}`:", nealeasă"):`: ${shift?name?.(shift.user_id):"neacoperit"}`}`;
  return onSelect?<button key={date} type="button" className={cls} disabled={disabled} aria-pressed={rank>=0||isExtra} aria-label={accessible} title={holiday||undefined} onClick={()=>onSelect(day)}>{children}</button>:<button key={date} type="button" className={cls} disabled={!onShift} onClick={()=>onShift?.(day)} aria-label={accessible} title={holiday||undefined}>{children}</button>;
 })}</div></div>;
}
function Selection({month,data,busy,save}:{month:string;data:Data;busy:boolean;save:(p:number[],a:number[])=>Promise<unknown>}){
 const stored=data.submissions.find(s=>s.month===month&&s.user_id===data.me!.id);const [preferred,setPreferred]=useState<number[]>(stored?.preferred??[]),[available,setAvailable]=useState<number[]>(stored?.available??[]),[stage,setStage]=useState(1),[saved,setSaved]=useState(false),[error,setError]=useState("");
 const toggle=(d:number)=>{setSaved(false);setError("");if(stage===1){if(preferred.includes(d))setPreferred(preferred.filter(x=>x!==d));else if(preferred.length<4){setPreferred([...preferred,d]);setAvailable(available.filter(x=>x!==d));}else toast.error("Maximum 4 gărzi preferate pentru această lună.");}else setAvailable(available.includes(d)?available.filter(x=>x!==d):[...available,d]);};
 useEffect(()=>{const handler=(event:Event)=>{const detail=(event as CustomEvent).detail;if(detail.month===month){setPreferred(detail.preferred);setAvailable(detail.available);setStage(2);setSaved(true);}};window.addEventListener("garda-selection-saved",handler);return()=>window.removeEventListener("garda-selection-saved",handler);},[month]);
 const [weekendRequired,setWeekendRequired]=useState<boolean|null>(null);
 useEffect(()=>{const controller=new AbortController();void fetch("/api/garda?view=preview&month="+encodeURIComponent(month),{cache:"no-store",signal:controller.signal}).then(async r=>{if(!r.ok)return;const p=await r.json() as MonthPreview;if(!controller.signal.aborted)setWeekendRequired(p.stats.weekendFree>0);}).catch(()=>{});return()=>controller.abort();},[month,data.me?.id,data.months.find(m=>m.id===month)?.version]);
 const ordered=stage===1?preferred:available;
 const reorder=(index:number,direction:number)=>{const next=[...ordered];[next[index],next[index+direction]]=[next[index+direction],next[index]];if(stage===1)setPreferred(next);else setAvailable(next);setSaved(false);};
 const finish=async()=>{setError("");try{await save(preferred,available);setSaved(true);}catch(e){setError((e as Error).message);}};
 return <div className="selection-layout"><section className="panel selection-panel"><div className="selection-heading"><h2 className="capitalize">{monthTitle(month)}</h2><span className="muted">{stage===1?"Preferințe · 1/2":"Disponibilitate · 2/2"}</span></div><CalendarGrid month={month} holidays={data.holidays} holidayPoints={data.holidayPoints} preferred={preferred} available={available} stage={stage} onSelect={toggle}/><div className="calendar-legend"><span><i className="unselected-dot"/>Nealeasă</span><span><i className="preferred-dot"/>Preferat</span><span><i className="available-dot"/>Disponibil suplimentar</span></div><p className="muted">{stage===1?"Selectează între 0 și 4 zile, în ordinea preferinței. Pentru 2–4 gărzi, alege cel puțin un weekend dacă mai sunt zile libere. Poți selecta zile consecutive; repartizarea va păstra pauza dintre gărzi.":`Alege în ordine cel puțin încă ${preferred.length} zile. Prima zi albastră are prioritatea 1.`}</p>{stage===2&&<div className="selection-progress"><span><CheckCircle2 size={17}/>{available.length} / {preferred.length} zile suplimentare</span><button className="text-btn" onClick={()=>{setAvailable([...available,...Array.from({length:monthDays(month)},(_,i)=>i+1).filter(d=>!preferred.includes(d)&&!available.includes(d))]);setSaved(false);}}>Selectează toate zilele rămase</button></div>}{error&&<div className="alert error" role="alert">{error}</div>}{saved&&<div className="alert success" role="status"><CheckCircle2 size={18}/>Preferințele și disponibilitatea au fost salvate. Le poți modifica până la închiderea înscrierilor.</div>}<div className="selection-actions">{stage===1?<><span>{preferred.length} gărzi solicitate</span><button className="btn primary" onClick={()=>{if(weekendRequired&&preferred.length>=2&&!preferred.some(d=>isWeekend(dateKey(month,d)))){setError("Alege cel puțin o preferință de weekend pentru 2–4 gărzi.");return;}setError("");setStage(2);}}>Continuă cu disponibilitatea</button></>:<><button className="btn secondary" onClick={()=>setStage(1)}>Înapoi la preferințe</button><button className="btn primary" disabled={busy||available.length<preferred.length} onClick={()=>void finish()}>{busy?"Se salvează…":preferred.length?"Salvează înscrierea":"Confirmă că nu solicit gărzi"}</button></>}</div></section><aside><section className="panel ordered-list"><h3>{stage===1?"Ordinea preferințelor":"Ordinea disponibilității"}</h3>{ordered.length?ordered.map((d,i)=><div key={d} className="preference-item"><span className={`preference-number ${stage===2?"availability-number":""}`}>{i+1}</span><div><strong>{d} {monthNames[Number(month.slice(5))-1]}</strong><small>{new Date(dateKey(month,d)+"T12:00:00Z").toLocaleDateString("ro-RO",{weekday:"long"})}</small></div><div className="reorder"><button aria-label={`Mută ziua ${d} mai sus`} disabled={i===0} onClick={()=>reorder(i,-1)}><ChevronLeft className="rotate-up" size={17}/></button><button aria-label={`Mută ziua ${d} mai jos`} disabled={i===ordered.length-1} onClick={()=>reorder(i,1)}><ChevronRight className="rotate-up" size={17}/></button></div><button className="remove-pref" aria-label={`Elimină ziua ${d}`} onClick={()=>{if(stage===1)setPreferred(preferred.filter(x=>x!==d));else setAvailable(available.filter(x=>x!==d));setSaved(false);}}><X size={16}/></button></div>):<p className="muted">Selectează prima zi în calendar.</p>}</section></aside></div>;
}
