 return <><div className="schedule-layout"><section className="panel schedule-panel"><div className="panel-title"><h2>{canSee&&shifts.length?"Programul gărzilor":"Calendarul lunii"}</h2>{canSee&&shifts.length>0&&<button className="btn secondary small-btn" onClick={exportCSV}><Download size={16}/>Export CSV</button>}</div>{selected.status==="locked"&&<div className="alert"><LockKeyhole size={18}/>Înscrierile se deschid pe 1 ale lunii precedente.</div>}{["open","closed","draft"].includes(selected.status)&&!admin&&<div className="alert"><Clock size={18}/>{selected.status==="open"?selected.deadline&&selected.deadline<=new Date().toISOString()?"Termenul de înscriere a expirat.":"Înscrierile sunt deschise pentru această lună.":"Înscrierile s-au închis."} Programul poate fi ajustat până la definitivarea din 20.</div>}{selected.status==="draft"&&admin&&uncovered>0&&<div className="alert warning"><AlertCircle size={18}/>{uncovered} zile neacoperite: {Array.from({length:monthDays(month)},(_,i)=>i+1).filter(d=>!shifts.some(s=>s.date===dateKey(month,d))).join(", ")}. Redeschide înscrierile sau atribuie manual unui medic disponibil.</div>}<CalendarGrid month={month} holidays={data.holidays} holidayPoints={data.holidayPoints} shifts={canSee?shifts:[]} name={name} meId={data.me!.id} onShift={admin&&(selected.status==="draft"||selected.status==="published"&&uncovered>0)?d=>{if(selected.status==="published"&&shifts.some(s=>s.date===dateKey(month,d)))return;setManualDay(d);setManualUser("");}:undefined}/><div className="calendar-legend"><span><i className="preferred-dot"/>Garda ta</span><span><i className="available-dot"/>Garda unui coleg</span><span><i className="unselected-dot"/>Zi neacoperită</span></div></section><aside><section className="panel"><h3>Gărzile tale</h3>{mine.length?mine.map(s=><div className="my-shift-item" key={s.date}><span className="date-square">{Number(s.date.slice(8))}<small>{monthNames[Number(month.slice(5))-1].slice(0,3)}</small></span><div><strong>{new Date(s.date+"T12:00:00Z").toLocaleDateString("ro-RO",{weekday:"long"})}</strong><p>{s.reason}</p></div></div>):<p className="muted">{sub?`${sub.preferred.length} gărzi solicitate. Programul este în pregătire.`:"Nicio gardă repartizată în această lună."}</p>}{["filling","draft","published"].includes(selected.status)&&mine.length>0&&<button className="btn secondary full" onClick={onSwap}><ArrowLeftRight size={17}/>Solicită un schimb</button>}</section>{admin&&selected.status==="draft"&&selected.report.conflicts&&<section className="panel conflict-report"><h3>Cum s-au rezolvat conflictele</h3>{selected.report.conflicts.length?selected.report.conflicts.map((c,i)=><p key={i}>{c}</p>):<p className="muted">Nu au existat conflicte între preferințe de același rang.</p>}{selected.report.deficits?.map(d=><p className="warning-text" key={d.id}>{d.name}: {d.assigned} din {d.requested} gărzi repartizate.</p>)}</section>}</aside></div>
 <Dialog open={manualDay!==null} onOpenChange={v=>{if(!v)setManualDay(null);}}><DialogContent><DialogHeader><DialogTitle>Atribuire manuală · ziua {manualDay}</DialogTitle><DialogDescription>Selectează un medic activ. Nu sunt permise gărzi consecutive, inclusiv între luni.</DialogDescription></DialogHeader><Picker value={manualUser} onChange={setManualUser} label="Alege medicul" items={data.users.filter(u=>u.active&&u.listed&&!data.shifts.some(s=>s.user_id===u.id&&[shiftDate(dateKey(month,manualDay??1),-1),shiftDate(dateKey(month,manualDay??1),1)].includes(s.date))).map(u=>({value:u.id,label:u.name}))}/><button className="btn primary" disabled={!manualUser||busy} onClick={()=>attempt(act("assign",{month,version:selected.version,day:manualDay,user_id:manualUser},"Garda a fost atribuită.").then(()=>setManualDay(null)))}>Atribuie garda</button></DialogContent></Dialog></>;
