function Swaps({data,name,busy,act,attempt,confirm}:{data:Data;name:(id:string)=>string;busy:boolean;act:Act;attempt:(p:Promise<unknown>)=>void;confirm:Confirm}){
 const [from,setFrom]=useState(""),[to,setTo]=useState("");const own=data.futureShifts.filter(s=>s.user_id===data.me!.id&&s.date>data.today),others=data.futureShifts.filter(s=>s.user_id!==data.me!.id&&s.date>data.today);
 return <><div className="page-heading"><div><h1>Schimburi</h1></div><ArrowLeftRight size={35} className="heading-icon"/></div><section className="panel swap-form"><div><h2>Cerere nouă</h2><p className="muted">Alege garda ta și garda pe care vrei să o preiei.</p></div><div className="swap-inputs"><label>Garda mea<Picker label="Alege garda ta" value={from} onChange={setFrom} items={own.map(s=>({value:s.date,label:dateLabel(s.date)}))}/></label><ArrowLeftRight size={21}/><label>Garda colegului<Picker label="Alege o gardă" value={to} onChange={setTo} items={others.map(s=>({value:s.date,label:`${dateLabel(s.date)} · ${name(s.user_id)}`}))}/></label><button className="btn primary" disabled={busy||!from||!to} onClick={()=>attempt(act("swap-request",{from,to},"Cererea a fost trimisă. Colegul a primit o notificare.").then(()=>{setFrom("");setTo("");}))}>Trimite cererea</button></div>{!own.length&&<p className="muted">Vei putea solicita schimburi când ai gărzi viitoare repartizate.</p>}</section><section className="panel swap-history"><h2>Cererile tale</h2>{!data.swaps.length?<Empty icon={ArrowLeftRight} title="Nicio cerere de schimb" text="Cererile trimise și primite vor apărea aici."/>:data.swaps.map(s=><article className="swap-card" key={s.id}><div><span className={`badge swap-${s.status}`}>{swapStates[s.status]}</span><h3>{name(s.requester)} <ArrowLeftRight size={16}/> {name(s.recipient)}</h3><p>{dateLabel(s.from_date)} <span>↔</span> {dateLabel(s.to_date)}</p><small>{new Date(s.created).toLocaleDateString("ro-RO")}</small></div>{s.status==="pending"&&<div className="swap-actions">{s.recipient===data.me!.id?<><button className="btn primary" disabled={busy} onClick={()=>confirm("Accepți schimbul?",`Vei face garda din ${dateLabel(s.from_date)}. Colegul va prelua garda ta din ${dateLabel(s.to_date)}.`,async()=>{await act("swap-answer",{id:s.id,answer:"accept"},"Schimbul a fost acceptat și programul actualizat.");})}>Acceptă</button><button className="btn secondary" disabled={busy} onClick={()=>attempt(act("swap-answer",{id:s.id,answer:"decline"},"Cererea a fost refuzată."))}>Refuză</button></>:<button className="btn secondary" disabled={busy} onClick={()=>attempt(act("swap-answer",{id:s.id,answer:"cancel"},"Cererea a fost anulată."))}>Anulează cererea</button>}</div>}</article>)}</section><RefusalList own={own} busy={busy} act={act} attempt={attempt} confirm={confirm}/></>;
}
function Administration({data,year,busy,act,attempt,confirm}:{data:Data;year:number;busy:boolean;act:Act;attempt:(p:Promise<unknown>)=>void;confirm:Confirm}){
 const [edit,setEdit]=useState<Person|null>(null),[points,setPoints]=useState(0),[active,setActive]=useState(true),[resetLink,setResetLink]=useState("");const [doctorName,setDoctorName]=useState("");const roster=data.users.filter(u=>u.listed);const [holidayDate,setHolidayDate]=useState(""),[holidayLabel,setHolidayLabel]=useState(""),[holidayEnabled,setHolidayEnabled]=useState(true),[holidayPoints,setHolidayPoints]=useState<5|10>(5);
 return <div className="admin-page"><div className="page-heading"><div><h1>Administrare</h1></div><span className="badge draft"><ShieldCheck size={15}/>Administrator</span></div><div className="admin-layout"><section className="panel team-panel"><div className="panel-title"><h2>Echipa</h2><span>{roster.length} medici</span></div>
 <form className="add-doctor-form" onSubmit={e=>{e.preventDefault();attempt(act("doctor-add",{name:doctorName},"Medicul a fost adăugat. Își poate activa contul din pagina de autentificare.").then(()=>setDoctorName("")));}}><label>Numele medicului<input name="doctor-name" value={doctorName} onChange={e=>setDoctorName(e.target.value)} placeholder="Nume și prenume" minLength={2} maxLength={80} required autoComplete="off"/></label><button className="btn primary" disabled={busy||doctorName.trim().length<2}><Plus size={17}/>Adaugă medic</button></form>
 <div className="doctor-roster">{roster.map(u=><article className="doctor-roster-row" key={u.id}><div className="doctor-roster-name"><strong>{u.name}</strong><small className="email-cell admin-desktop-only">{u.role==="admin"?"Administrator · ":""}{u.email??"Emailul va fi adăugat la prima accesare"}</small></div><span className={`badge admin-desktop-only ${u.active?u.registered?"completed":"draft":"closed"}`}>{!u.active?"Suspendat":u.registered?"Cont activat":"Prima accesare"}</span><span className="admin-desktop-only">{u.base_points} P inițiale</span><button className="btn secondary small-btn admin-desktop-only" onClick={()=>{setEdit(u);setPoints(u.base_points);setActive(!!u.active);setResetLink("");}}>Gestionează</button>{u.role==="admin"?<span className="roster-owner">Administrator</span>:<button className="btn danger small-btn" disabled={busy} aria-label={`Șterge medicul ${u.name}`} onClick={()=>confirm(`Ștergi medicul ${u.name}?`,"Medicul este scos din echipă și nu se mai poate conecta. Istoricul gărzilor și punctajele se păstrează. Îl poți readăuga ulterior cu același nume.",async()=>{await act("doctor-remove",{id:u.id},"Medicul a fost scos din echipă.");})}><Trash2 size={15}/>Șterge</button>}</article>)}</div></section></div>
 <div className="admin-desktop-only">
 <details className="admin-details"><summary>Resetarea conturilor</summary><section className="panel reset-accounts-panel"><div><h2>Resetarea tuturor conturilor</h2><p className="muted">Șterge emailurile de recuperare și parolele tuturor conturilor, inclusiv contul tău, și deconectează toate sesiunile. Lista medicilor, gărzile, preferințele și punctajele se păstrează.</p><p className="muted">După resetare, vei alege o parolă nouă pentru Pecie Mihai. Fiecare medic își va activa apoi propriul cont. Parolele salvate deja în Chrome se șterg separat din managerul de parole.</p></div><button className="btn danger" disabled={busy} onClick={()=>confirm("Resetezi toate conturile?","Toate parolele și emailurile medicilor vor fi șterse. Gărzile și punctajele rămân. Vei fi redirecționat către configurarea propriului cont de administrator; linkul privat este valabil o oră.",async()=>{const result=await act("reset-accounts",{confirmation:"RESETARE"},"");if(result.link)location.assign(result.link);})}>Resetează toate conturile</button></section></details>
 {!data.emailReady&&<details className="admin-details"><summary>Recuperarea parolelor</summary><div className="alert warning"><Mail size={18}/><span>Recuperarea automată prin email nu este încă activată. Până la conectarea serviciului de email, poți genera un link de resetare din „Gestionează” pentru fiecare medic.</span></div></details>}
 <details className="admin-details"><summary>Sărbători și istoric</summary><section className="panel holiday-admin"><h2>Sărbători legale · {year}</h2><p className="muted">Calendarul include sărbătorile naționale și Paștele ortodox. Adaugă sau exclude zile înainte de generarea programului. Cele trei zile de Paște, Crăciunul 25–27 decembrie și Revelionul (31 decembrie) sunt punctate cu 10 P. Poți adapta zilele și punctajele înainte de generarea programului.</p><div className="holiday-tags">{Object.entries(data.holidays).sort().map(([d,n])=><span key={d}><strong>{d.slice(8)}.{d.slice(5,7)}</strong>{n} · {dayPoints(d,data.holidays,data.holidayPoints)} P</span>)}</div><div className="holiday-form"><label>Data<input type="date" value={holidayDate} onChange={e=>setHolidayDate(e.target.value)} min={`${year}-01-01`} max={`${year}-12-31`}/></label><label>Denumire<input value={holidayLabel} onChange={e=>setHolidayLabel(e.target.value)} placeholder="Denumirea sărbătorii" maxLength={100}/></label><label>Puncte<select value={holidayPoints} onChange={e=>setHolidayPoints(Number(e.target.value) as 5|10)}><option value={5}>Sărbătoare legală · 5 P</option><option value={10}>Sărbătoare mare · 10 P</option></select></label><label className="switch-label"><Switch checked={holidayEnabled} onCheckedChange={setHolidayEnabled}/>Sărbătoare activă</label><button className="btn secondary" disabled={busy||!holidayDate||holidayLabel.length<2} onClick={()=>attempt(act("holiday",{date:holidayDate,label:holidayLabel,enabled:holidayEnabled?1:0,points:holidayPoints},"Calendarul sărbătorilor a fost actualizat."))}>Salvează</button></div><p className="source-note">Sărbători naționale: <a href="https://reges.inspectiamuncii.ro/informatii-utile/codul-muncii/" target="_blank" rel="noreferrer">Codul muncii, art. 139</a>. Adaptările echipei rămân la decizia administratorului.</p></section>
 <section className="panel"><h2>Istoricul modificărilor</h2>{data.events.length?<div className="audit-list">{data.events.map((e,i)=><div key={i}><strong>{e.action}</strong><span>{e.name} · {new Date(e.created).toLocaleString("ro-RO")}</span></div>)}</div>:<p className="muted">Modificările programului și ale conturilor vor apărea aici.</p>}</section></details>
 </div>
 <Dialog open={!!edit} onOpenChange={v=>{if(!v)setEdit(null);}}><DialogContent className="app-dialog"><DialogHeader><DialogTitle>{edit?.name}</DialogTitle><DialogDescription>{edit?.email??"Medicul își adaugă emailul și parola la prima accesare."}</DialogDescription></DialogHeader><label className="switch-label"><Switch checked={active} onCheckedChange={setActive} disabled={edit?.role==="admin"}/>Acces activ în echipă</label><label>Puncte inițiale<input type="number" min={0} max={100000} value={points} onChange={e=>setPoints(Number(e.target.value))}/></label><p className="muted">Folosește punctele inițiale pentru gărzile dinaintea utilizării aplicației. Punctele programelor definitive se adaugă automat.</p><button className="btn primary" disabled={busy} onClick={()=>attempt(act("user-update",{id:edit?.id,active:active?1:0,base_points:points},"Contul a fost actualizat.").then(()=>setEdit(null)))}>Salvează contul</button><hr/><button className="btn secondary" disabled={busy||!edit?.registered} onClick={()=>attempt(act("admin-reset",{id:edit?.id},"").then(r=>setResetLink(r.link)))}>Generează link de resetare a parolei</button>{resetLink&&<div className="reset-link-box"><p>Link valabil 30 de minute. Transmite-l numai titularului contului.</p><input readOnly value={resetLink} aria-label="Link de resetare"/><button className="btn secondary" onClick={()=>{void navigator.clipboard.writeText(resetLink).then(()=>toast.success("Link copiat.")).catch(()=>toast.error("Selectează și copiază linkul manual."));}}>Copiază linkul</button></div>}</DialogContent></Dialog></div>;
}
function Account({busy,act}:{busy:boolean;act:Act}){const [error,setError]=useState("");return <form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);setError("");if(f.get("password")!==f.get("confirm")){setError("Parolele noi nu coincid.");return;}const form=e.currentTarget;try{await act("password",{current:f.get("current"),password:f.get("password")},"Parola a fost schimbată. Celelalte sesiuni au fost deconectate.");form.reset();}catch(e){setError((e as Error).message);}}}><label>Parola actuală<input name="current" type="password" required autoComplete="current-password"/></label><label>Parola nouă<input name="password" type="password" required minLength={10} maxLength={128} autoComplete="new-password"/></label><label>Confirmă parola nouă<input name="confirm" type="password" required minLength={10} maxLength={128} autoComplete="new-password"/></label>{error&&<div className="alert error">{error}</div>}<button className="btn primary full" disabled={busy}>Schimbă parola</button></form>;}
